1	/**
2	 * Git-aware isolated operations: every unit runs on its own worktree/branch created from the operation's integration
3	 * tip, and a completed unit is committed and merged into an operation integration worktree before the scheduler sees it
4	 * as complete. The operator's checkout is never touched, and nothing here runs when the operation did not opt in
5	 * (`state.git` absent).
6	 *
7	 * Integration is the only place the operation writes Git history. It is idempotent: a recorded receipt, or a branch
8	 * whose tip is already an ancestor of the integration branch, is recognised on resume, so a crash between the merge and
9	 * the persisted transition does not merge twice. A textual conflict aborts the merge, leaves both branches intact, and
10	 * returns a decision for the operator. A mechanically clean merge whose merged tree fails the unit's verifier is reset
11	 * and reported as an integration failure.
12	 */
13	import { execFileSync } from "node:child_process";
14	import { createHash } from "node:crypto";
15	import * as fs from "node:fs";
16	import * as os from "node:os";
17	import * as path from "node:path";
18	import { trustedGitArgs } from "../git.js";
19	import { ensureGitExclude } from "./git_exclude.js";
20	import { GIT_SAFE, attributesTree, driverRefusal, safeGitEnv, snapshotSupport } from "./specialist_inputs.js";
21	import { environmentHint, runVerifierShell, verifierTimeoutSecs } from "../tester.js";
22	import type {
23	  IntegrationReceipt,
24	  OperationGitState,
25	  OperationGitUnit,
26	  UnitRunResult,
27	  WorkUnit,
28	} from "./operation.js";
29	
30	const GIT_TIMEOUT_MS = 300_000;
31	
32	function git(cwd: string, args: string[]): string {
33	  return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: GIT_TIMEOUT_MS }).trim();
34	}
35	
36	function gitResult(cwd: string, args: string[]): { ok: boolean; stdout: string; stderr: string } {
37	  try {
38	    const stdout = execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: GIT_TIMEOUT_MS });
39	    return { ok: true, stdout, stderr: "" };
40	  } catch (error: any) {
41	    return { ok: false, stdout: String(error?.stdout ?? ""), stderr: String(error?.stderr ?? error?.message ?? "") };
42	  }
43	}
44	
45	/** Filesystem- and ref-safe name; the hash keeps two ids that sanitise the same apart. */
46	export function gitSlug(value: string): string {
47	  const clean = value.toLowerCase().replace(/[^a-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "unit";
48	  return `${clean}-${createHash("sha256").update(value).digest("hex").slice(0, 8)}`;
49	}
50	
51	export interface OperationGitPlan {
52	  key: string;
53	  repoRoot: string;
54	  baseRef: string;
55	  baseCommit: string;
56	  integrationBranch: string;
57	  integrationWorktree: string;
58	  baseDir: string;
59	}
60	
61	/** Where the operation's worktrees live, and what it integrates into. Reads Git; writes nothing. */
62	export function planOperationGit(workspace: string, operationId: string, baseRef = "HEAD"): OperationGitPlan {
63	  let repoRoot: string;
64	  try {
65	    repoRoot = git(workspace, ["rev-parse", "--show-toplevel"]);
66	  } catch {
67	    throw new Error(`git isolation needs a Git repository (${workspace} is not one)`);
68	  }
69	  let baseCommit: string;
70	  try {
71	    baseCommit = git(repoRoot, ["rev-parse", "--verify", `${baseRef}^{commit}`]);
72	  } catch {
73	    throw new Error(`git isolation base '${baseRef}' does not name a commit`);
74	  }
75	  const key = gitSlug(operationId);
76	  const baseDir = path.join(repoRoot, ".nexus", "worktrees", `op-${key}`);
77	  return {
78	    key,
79	    repoRoot,
80	    baseRef,
81	    baseCommit,
82	    integrationBranch: `nexus/op-${key}/integration`,
83	    integrationWorktree: path.join(baseDir, "integration"),
84	    baseDir,
85	  };
86	}
87	
88	/** Fresh persisted state for a newly planned isolated operation. */
89	export function newOperationGitState(plan: OperationGitPlan): OperationGitState {
90	  return {
91	    isolate: true,
92	    repoRoot: plan.repoRoot,
93	    baseRef: plan.baseRef,
94	    baseCommit: plan.baseCommit,
95	    integrationBranch: plan.integrationBranch,
96	    integrationWorktree: plan.integrationWorktree,
97	    baseDir: plan.baseDir,
98	    units: {},
99	  };
100	}
101	
102	export type IntegrateResult =
103	  | { kind: "integrated" | "nothing"; receipt: IntegrationReceipt }
104	  | { kind: "conflict"; files: string[]; tip: string }
105	  | { kind: "failed"; reason: string };
106	
107	/** What the runner observed about the unit it is integrating; omitted fields are omitted from the receipt. */
108	export interface IntegrationEvidence {
109	  sequence?: number;
110	  candidate?: { digest: string; scope: "tree" | "commit" };
111	  tests?: { command: string; status: string; hasExecutedTests: boolean; definitionBound?: false };
112	}
113	
114	function evidenceFields(evidence: IntegrationEvidence): Pick<IntegrationReceipt, "sequence" | "candidate" | "tests"> {
115	  return {
116	    ...(evidence.sequence !== undefined ? { sequence: evidence.sequence } : {}),
117	    ...(evidence.candidate ? { candidate: evidence.candidate } : {}),
118	    ...(evidence.tests ? { tests: evidence.tests } : {}),
119	  };
120	}
121	
122	/**
123	 * Create the integration worktree/branch if it is not there yet. Recovery reuses an existing checkout; a worktree that
124	 * exists while its branch is gone, or vice versa, is a broken pair and fails closed.
125	 */
126	export function ensureIntegrationWorktree(plan: OperationGitPlan, state: OperationGitState, options: { hasHistory?: boolean } = {}): void {
127	  const branchExists = gitResult(plan.repoRoot, ["rev-parse", "--verify", `refs/heads/${plan.integrationBranch}`]).ok;
128	  const worktreeExists = fs.existsSync(plan.integrationWorktree);
129	  if (branchExists && worktreeExists) return;
130	  if (!branchExists && worktreeExists) {
131	    throw new Error("the integration worktree exists but its branch is gone; restore the branch or remove the worktree");
132	  }
133	  if (!branchExists && !worktreeExists && options.hasHistory) {
134	    // Recreating from baseCommit would silently drop every integrated unit; only the operator can restore it.
135	    throw new Error(
136	      "the integration branch and worktree are gone but this operation already integrated work; restore the branch or start a new operation",
137	    );
138	  }
139	  ensureGitExclude(plan.repoRoot);
140	  fs.mkdirSync(plan.baseDir, { recursive: true });
141	  // A missing worktree with the branch still present is repaired in place (the branch is the source of truth).
142	  gitResult(plan.repoRoot, ["worktree", "prune", "--expire", "now"]);
143	  const added = branchExists
144	    ? gitResult(plan.repoRoot, ["worktree", "add", plan.integrationWorktree, plan.integrationBranch])
145	    : gitResult(plan.repoRoot, ["worktree", "add", "-b", plan.integrationBranch, plan.integrationWorktree, plan.baseCommit]);
146	  if (!added.ok) throw new Error(`cannot create the integration worktree: ${added.stderr.trim() || "git worktree add failed"}`);
147	}
148	
149	/** Remove an integration worktree/branch created for an operation that could not start. */
150	export function discardIntegrationWorktree(plan: OperationGitPlan): void {
151	  if (fs.existsSync(plan.integrationWorktree)) {
152	    gitResult(plan.repoRoot, ["worktree", "remove", "--force", plan.integrationWorktree]);
153	  }
154	  gitResult(plan.repoRoot, ["branch", "-D", plan.integrationBranch]);
155	}
156	
157	export interface UnitGitPreparation {
158	  workspace: string;
159	  branch: string;
160	  /** True when an existing worktree was reused (resume/retry). */
161	  reused: boolean;
162	  /** True when a stale diagnostic snapshot was discarded for a fresh one: a conversation about the old one is void. */
163	  snapshotReplaced?: boolean;
164	}
165	
166	export class OperationGit {
167	  /** Empty directory used as `core.hooksPath` for mechanical integration commits/merges. */
168	  private readonly hooksDir: string;
169	
170	  constructor(
171	    private readonly plan: OperationGitPlan,
172	    private readonly state: OperationGitState,
173	    private readonly options: { verifyTimeoutSecs?: number } = {},
174	  ) {
175	    this.hooksDir = path.join(plan.baseDir, "no-hooks");
176	  }
177	
178	  currentTip(): string {
179	    return git(this.plan.integrationWorktree, ["rev-parse", "HEAD"]);
180	  }
181	
182	  /**
183	   * Receipts whose integrated commit is no longer an ancestor of the integration tip: the branch was rewritten or
184	   * rewound in place. The operation must stop rather than continue on a tree that silently lost accepted work.
185	   */
186	  historyProblems(receipts: readonly IntegrationReceipt[]): Array<{ unitId: string; integratedCommit: string }> {
187	    const problems: Array<{ unitId: string; integratedCommit: string }> = [];
188	    for (const receipt of receipts) {
189	      const reachable = receipt.integratedCommit &&
190	        gitResult(this.plan.integrationWorktree, ["merge-base", "--is-ancestor", receipt.integratedCommit, "HEAD"]).ok;
191	      if (!reachable) problems.push({ unitId: receipt.unitId, integratedCommit: receipt.integratedCommit });
192	    }
193	    return problems;
194	  }
195	
196	  /**
197	   * Give the unit a worktree branched from the integration tip. A recorded worktree is reused so a retry or a resume
198	   * continues on the same files; an operator restart throws the old worktree and branch away first.
199	   */
200	  prepareUnit(unit: WorkUnit, options: { restart?: boolean; snapshotOf?: string; snapshotRun?: string } = {}): UnitGitPreparation {
201	    const recorded = this.state.units[unit.id];
202	    const branch = recorded?.branch ?? `nexus/op-${this.plan.key}/${gitSlug(unit.id)}`;
203	    const worktree = recorded?.worktree ?? path.join(this.plan.baseDir, "units", gitSlug(unit.id));
204	
205	    // A snapshot belongs to one failed run of its dependency. When the dependency has failed again since, the old
206	    // checkout shows a candidate that no longer exists: discard it (it is diagnostic and never integrated).
207	    const staleSnapshot = Boolean(recorded && options.snapshotOf
208	      && (recorded.snapshotOf !== options.snapshotOf || recorded.snapshotRun !== options.snapshotRun));
209	    const restart = Boolean((options.restart || staleSnapshot) && recorded);
210	    // A restart onto a fresh snapshot builds it first: when it cannot be built the old worktree and branch are still there.
211	    let snapshot = restart && options.snapshotOf ? this.snapshotCandidate(options.snapshotOf) : undefined;
212	    let restartBranch = branch;
213	    if (restart) {
214	      // The worktree may be gone while its registration survives; prune before deleting the branch, or `branch -D`
215	      // refuses and the restart silently resumes the old work.
216	      this.removeWorktree(recorded!.worktree);
217	      gitResult(this.plan.repoRoot, ["worktree", "prune", "--expire", "now"]);
218	      gitResult(this.plan.repoRoot, ["branch", "-D", recorded!.branch]);
219	    }
220	
221	    if (fs.existsSync(worktree) && !restart) {
222	      const existing = this.state.units[unit.id];
223	      if (!existing) {
224	        throw new Error(`worktree ${worktree} exists but is not recorded for unit ${unit.id}; remove it or restart the unit`);
225	      }
226	      return { workspace: worktree, branch: existing.branch, reused: true };
227	    }
228	    if (fs.existsSync(worktree) && restart) gitResult(this.plan.repoRoot, ["worktree", "remove", "--force", worktree]);
229	
230	    let branchExists = gitResult(this.plan.repoRoot, ["rev-parse", "--verify", `refs/heads/${branch}`]).ok;
231	    if (restart && branchExists) {
232	      // Still checked out elsewhere: a restart must start from the tip, so use a fresh branch rather than resume it.
233	      restartBranch = `${branch}-${gitSlug(`${unit.id}-${Date.now()}`)}`;
234	      branchExists = false;
235	    }
236	    // A failure_debugger on a failed dependency starts from that dependency's candidate, which was never integrated.
237	    snapshot ??= !branchExists && options.snapshotOf ? this.snapshotCandidate(options.snapshotOf) : undefined;
238	    const startPoint = snapshot ?? this.currentTip();
239	    const add = () => branchExists
240	      ? gitResult(this.plan.repoRoot, ["worktree", "add", worktree, restartBranch])
241	      : gitResult(this.plan.repoRoot, ["worktree", "add", "-b", restartBranch, worktree, startPoint]);
242	    // A worktree directory that disappeared outside Nexus leaves a registration behind; prune it, then add.
243	    gitResult(this.plan.repoRoot, ["worktree", "prune", "--expire", "now"]);
244	    let added = add();
245	    if (!added.ok && /already registered|missing but already registered/i.test(added.stderr)) {
246	      gitResult(this.plan.repoRoot, ["worktree", "remove", "--force", worktree]);
247	      gitResult(this.plan.repoRoot, ["worktree", "prune", "--expire", "now"]);
248	      added = add();
249	    }
250	    if (!added.ok) throw new Error(`cannot create a worktree for ${unit.id}: ${added.stderr.trim() || "git worktree add failed"}`);
251	
252	    const baseCommit = branchExists
253	      ? gitResult(this.plan.repoRoot, ["merge-base", this.plan.integrationBranch, restartBranch]).stdout.trim() || this.currentTip()
254	      : startPoint;
255	    const snapshotOf = snapshot ? options.snapshotOf : branchExists ? recorded?.snapshotOf : undefined;
256	    const snapshotRun = snapshot ? options.snapshotRun : branchExists ? recorded?.snapshotRun : undefined;
257	    // Only now is the old record replaced; a failed add leaves the previous entry intact so a retry can restart.
258	    this.state.units[unit.id] = {
259	      branch: restartBranch, worktree, baseCommit,
260	      ...(snapshotOf ? { snapshotOf } : {}), ...(snapshotRun ? { snapshotRun } : {}),
261	    };
262	    return { workspace: worktree, branch: restartBranch, reused: false, ...(staleSnapshot && snapshot ? { snapshotReplaced: true } : {}) };
263	  }
264	
265	  /**
266	   * Commit the unit's working tree, merge its branch into the integration branch, and re-run its verifier on the merged
267	   * tree before the receipt is recorded. A conflict aborts the merge; a verification failure resets it.
268	   */
269	  /**
270	   * Merges a completed unit's branch into the operation branch. `evidence` is supplied by the runner: the merge
271	   * order and the candidate/tests the unit was accepted with. Direct callers (tests) may omit it; the receipt then
272	   * honestly omits the fields rather than inventing them.
273	   */
274	  async integrate(
275	    unit: WorkUnit,
276	    result: Extract<UnitRunResult, { kind: "completed" }>,
277	    evidence: IntegrationEvidence = {},
278	  ): Promise<IntegrateResult> {
279	    const entry = this.state.units[unit.id];
280	    if (!entry) return { kind: "failed", reason: `unit ${unit.id} has no worktree recorded` };
281	    if (entry.integratedCommit) {
282	      return {
283	        kind: "nothing",
284	        receipt: {
285	          unitId: unit.id,
286	          branch: entry.branch,
287	          commit: entry.integratedCommit,
288	          integratedCommit: entry.integratedCommit,
289	          mergedAt: new Date().toISOString(),
290	          files: [],
291	          outcome: result.outcome,
292	          summary: result.summary,
293	          verification: "ALREADY_INTEGRATED",
294	          ...evidenceFields(evidence),
295	        },
296	      };
297	    }
298	    const worktreeMissing = !fs.existsSync(entry.worktree);
299	    const recoveredCommit = worktreeMissing ? this.mergedUnitCommit(entry) : undefined;
300	    if (worktreeMissing && !recoveredCommit) {
301	      return { kind: "failed", reason: `unit ${unit.id}'s worktree is missing (${entry.worktree})` };
302	    }
303	
304	    if (!worktreeMissing) {
305	      const branch = gitResult(entry.worktree, ["rev-parse", "--abbrev-ref", "HEAD"]);
306	      if (!branch.ok || branch.stdout.trim() !== entry.branch) {
307	        return { kind: "failed", reason: `unit ${unit.id}'s worktree is not on its recorded branch ${entry.branch}` };
308	      }
309	
310	      // Uncommitted agent work is the normal case; commit it without touching ignored build output.
311	      const dirty = gitResult(entry.worktree, ["status", "--porcelain"]).stdout.trim();
312	      if (dirty) {
313	        const added = gitResult(entry.worktree, ["add", "-A"]);
314	        if (!added.ok) return { kind: "failed", reason: `cannot stage ${unit.id}: ${added.stderr.trim()}` };
315	        const committed = gitResult(entry.worktree, [
316	          ...this.mechanicalGitConfig(), "commit", "--no-verify", "-q", "-m", `nexus: ${unit.title}`,
317	        ]);
318	        if (!committed.ok) {
319	          return { kind: "failed", reason: `cannot commit ${unit.id}: ${committed.stderr.trim() || "git commit failed"}` };
320	        }
321	      }
322	    }
323	    const commit = recoveredCommit ?? git(entry.worktree, ["rev-parse", "HEAD"]);
324	    if (commit === entry.baseCommit) {
325	      const tip = this.currentTip();
326	      this.state.units[unit.id] = { ...entry, integratedCommit: tip };
327	      return {
328	        kind: "nothing",
329	        receipt: {
330	          unitId: unit.id,
331	          branch: entry.branch,
332	          commit,
333	          integratedCommit: tip,
334	          mergedAt: new Date().toISOString(),
335	          files: [],
336	          outcome: result.outcome,
337	          summary: result.summary,
338	          verification: "NO_CHANGES",
339	          ...evidenceFields(evidence),
340	        },
341	      };
342	    }
343	
344	    const tip = this.currentTip();
345	    // A branch already contained in the integration tip (crash after the merge) is recorded, not merged twice.
346	    if (gitResult(this.plan.integrationWorktree, ["merge-base", "--is-ancestor", commit, "HEAD"]).ok) {
347	      // The merge happened before a crash. The merged tree can no longer be reset safely, so the verifier is a
348	      // post-hoc check: a failure is reported for the operator, not silently recorded as verified.
349	      const posthoc = result.verification?.command && result.verification.status === "PASSED" && result.verification.hasExecutedTests
350	        ? this.verifyMerged(result.verification.command)
351	        : undefined;
352	      const integrity = posthoc ? this.integrationIntegrity(commit, tip) : undefined;
353	      if (integrity && !integrity.ok) {
354	        const reason = integrity.reason ?? "integration verification changed the integration history";
355	        const restoration = this.restoreIntegration(tip);
356	        return { kind: "failed", reason: restoration ? `${reason}; ${restoration}` : reason };
357	      }
358	      if (posthoc) this.cleanIntegrationWorktree();
359	      if (posthoc && !posthoc.ok) {
360	        // Do not record this as integrated: a retry must re-check the merged tree (and may add the missing work).
361	        return { kind: "failed", reason: `${posthoc.reason ?? "integration verification failed"} (the merge is already in place; inspect and retry or stop)` };
362	      }
363	      this.state.units[unit.id] = { ...entry, integratedCommit: tip };
364	      return {
365	        kind: "nothing",
366	        receipt: {
367	          unitId: unit.id,
368	          branch: entry.branch,
369	          commit,
370	          integratedCommit: tip,
371	          mergedAt: new Date().toISOString(),
372	          files: [],
373	          outcome: result.outcome,
374	          summary: result.summary,
375	          verification: posthoc ? (result.verification?.definitionBound === false ? "PASSED_POSTHOC_UNBOUND" : "PASSED_POSTHOC") : "ALREADY_MERGED",
376	          ...evidenceFields(evidence),
377	        },
378	      };
379	    }
380	
381	    this.abortStaleMerge();
382	    if (gitResult(this.plan.integrationWorktree, ["status", "--porcelain"]).stdout.trim()) {
383	      return { kind: "failed", reason: "the integration worktree has uncommitted changes; clean it before integrating" };
384	    }
385	
386	    // Integration is mechanical: no commit hooks or signing, because the merged tree is re-verified instead. The unit's
387	    // own commit uses the same settings so a signing prompt cannot hang a headless operation.
388	    const merged = gitResult(this.plan.integrationWorktree, [
389	      ...this.mechanicalGitConfig(),
390	      "merge", "--no-ff", "--no-verify", "-m", `nexus: integrate ${unit.id} — ${unit.title}`, entry.branch,
391	    ]);
392	    if (!merged.ok) {
393	      const conflicted = gitResult(this.plan.integrationWorktree, ["diff", "--name-only", "--diff-filter=U"]).stdout
394	        .split("\n").map((line) => line.trim()).filter(Boolean).sort();
395	      gitResult(this.plan.integrationWorktree, ["merge", "--abort"]);
396	      return { kind: "conflict", files: conflicted, tip };
397	    }
398	
399	    const mergedTip = this.currentTip();
400	    const verification = result.verification?.command && result.verification.status === "PASSED" && result.verification.hasExecutedTests
401	      ? this.verifyMerged(result.verification.command)
402	      : undefined;
403	    const integrity = verification ? this.integrationIntegrity(commit, mergedTip) : undefined;
404	    if (verification && (!verification.ok || (integrity && !integrity.ok))) {
405	      // The merge is mechanically clean but the merged tree does not pass the unit's verifier: undo it.
406	      const reason = integrity?.reason ?? verification.reason ?? "integration verification failed";
407	      const restoration = this.restoreIntegration(tip);
408	      return { kind: "failed", reason: restoration ? `${reason}; ${restoration}` : reason };
409	    }
410	    if (verification) this.cleanIntegrationWorktree();
411	
412	    const integratedCommit = this.currentTip();
413	    const files = gitResult(this.plan.repoRoot, ["diff", "--name-only", tip, integratedCommit]).stdout
414	      .split("\n").map((line) => line.trim()).filter(Boolean).sort();
415	    const receipt: IntegrationReceipt = {
416	      unitId: unit.id,
417	      branch: entry.branch,
418	      commit,
419	      integratedCommit,
420	      mergedAt: new Date().toISOString(),
421	      files,
422	      outcome: result.outcome,
423	      summary: result.summary,
424	      verification: verification ? (result.verification?.definitionBound === false ? "PASSED_UNBOUND" : "PASSED") : "NOT_RUN",
425	      ...evidenceFields(evidence),
426	    };
427	    this.state.units[unit.id] = { ...entry, integratedCommit };
428	    return { kind: "integrated", receipt };
429	  }
430	
431	  /**
432	   * A commit of `unitId`'s worktree as it stands on top of its HEAD: everything in that unit's index (including files
433	   * force-added past .gitignore), their worktree edits and deletions, and untracked non-ignored files. Built in a
434	   * private copy of the unit's index so that unit's index, branch and files are untouched. Throws when it cannot be built:
435	   * a debugger must not silently fall back to a tree without the failure it is meant to reproduce.
436	   */
437	  private snapshotCandidate(unitId: string): string {
438	    const entry = this.state.units[unitId];
439	    if (!entry || !fs.existsSync(entry.worktree)) throw new Error(`unit ${unitId}'s worktree is not available to snapshot`);
440	    // Host-side git runs only where the checkout is trusted: the unit's model owns this worktree and may have replaced
441	    // its `.git` pointer or planted a repository in it. Refused (throws) before anything is read or copied.
442	    const pin = trustedGitArgs(entry.worktree);
443	    const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-candidate-snapshot-"));
444	    // Pinned like the candidate diff: nothing the (model-written) worktree configures may run here. No inherited GIT_*,
445	    // no fsmonitor or hooks, and attributes from a stripped copy of the worktree's own .gitattributes (filter and diff
446	    // drivers removed, text/eol kept), so no clean filter runs; a driver assigned through $GIT_DIR/info/attributes
447	    // refuses the snapshot instead of being run.
448	    let attrs: ReturnType<typeof attributesTree>;
449	    // `raw` keeps the output verbatim (NUL-separated listings: a path may start or end with whitespace); scalar results
450	    // are trimmed.
451	    const run = (args: string[], options: { input?: string; ownIndex?: boolean; raw?: boolean } = {}) => {
452	      const out = execFileSync("git", [...pin, ...GIT_SAFE, ...args], {
453	        cwd: entry.worktree, encoding: "utf8", stdio: [options.input === undefined ? "ignore" : "pipe", "pipe", "pipe"], timeout: GIT_TIMEOUT_MS,
454	        env: safeGitEnv(options.ownIndex ? undefined : path.join(scratch, "index"), attrs), maxBuffer: 256 * 1024 * 1024,
455	        ...(options.input === undefined ? {} : { input: options.input }),
456	      });
457	      return options.raw ? out : out.trim();
458	    };
459	    try {
460	      // Only a repository state the predicate covers is snapshotted (no sparse checkout, assume-unchanged or skip-worktree
461	      // flags, gitlinks, unresolved merge, unreliable modes); anything else is refused with its reason, never guessed at.
462	      const support = snapshotSupport((args) => run(args, { ownIndex: true, raw: true }), entry.worktree);
463	      if ("unsupported" in support) throw new Error(`the failing candidate cannot be snapshotted: ${support.unsupported}; fix that state in the unit's worktree and retry, or stop`);
464	      const ownIndex = run(["rev-parse", "--path-format=absolute", "--git-path", "index"], { ownIndex: true, raw: true }).replace(/\n$/, "");
465	      try {
466	        fs.copyFileSync(ownIndex, path.join(scratch, "index"));
467	      } catch (err: any) {
468	        // Only a repository without an index yet (nothing staged) starts from HEAD; any other failure would silently drop the unit's staged state.
469	        if (err?.code !== "ENOENT") throw err;
470	        run(["read-tree", "HEAD"]);
471	      }
472	      const listed = run(["ls-files", "-z", "--cached", "--others", "--exclude-standard"], { raw: true }).split("\0").filter(Boolean);
473	      // A directory entry (trailing slash) is an untracked nested git repository, which `git add` refuses or embeds: skipped, as in the candidate diff.
474	      const nested = listed.filter((p) => p.endsWith("/"));
475	      const files = listed.filter((p) => !p.endsWith("/"));
476	      // The worktree's own .gitattributes without filter and diff assignments, as for the candidate diff, so text/eol
477	      // normalization applies to the snapshot exactly as it would to the tester's own commit.
478	      attrs = attributesTree(entry.worktree, scratch, files, pin);
479	      const refusal = driverRefusal((args, input) => run(args, { input, raw: true }), files);
480	      if (refusal) throw new Error(refusal);
481	      run(["add", "-A", "--", ".", ...nested.map((p) => `:(exclude,literal)${p.slice(0, -1)}`)]);
482	      const tree = run(["write-tree"]);
483	      const commit = run([...this.mechanicalGitConfig(), "commit-tree", tree, "-p", "HEAD", "-m", `nexus: snapshot of ${unitId}'s candidate for failure debugging`]);
484	      // Git reuses an object it finds in the private attribute store (an alternate) instead of writing its own copy, so
485	      // the snapshot would depend on a store removed below: pack everything the commit adds (alternate objects included)
486	      // into the repository first.
487	      if (attrs) {
488	        const objects = run(["rev-parse", "--path-format=absolute", "--git-path", "objects"], { ownIndex: true });
489	        run(["pack-objects", "--revs", "--quiet", path.join(objects, "pack", "pack")], { input: `${commit}\n^HEAD\n`, ownIndex: true });
490	      }
491	      return commit;
492	    } finally {
493	      fs.rmSync(scratch, { recursive: true, force: true });
494	    }
495	  }
496	
497	  /** Whether the unit's branch is a diagnostic snapshot of another unit's unverified candidate (never integrated). */
498	  isSnapshotUnit(unitId: string): boolean {
499	    return this.state.units[unitId]?.snapshotOf !== undefined;
500	  }
501	
502	  /** Remove a completed unit's clean worktree (its branch and receipt stay). */
503	  disposeUnit(unitId: string): void {
504	    const entry = this.state.units[unitId];
505	    if (entry) this.removeWorktree(entry.worktree, true);
506	  }
507	
508	  /**
509	   * Unit worktrees that were deliberately kept instead of removed, with the reason. The operator is told about them:
510	   * a retained worktree holds uncommitted or ignored work, so silently keeping it would hide work and silently
511	   * removing it would destroy it.
512	   */
513	  preservedWorktrees(unitIds?: string[]): Array<{ unitId: string; worktree: string; reason: "dirty" | "ignored" }> {
514	    const out: Array<{ unitId: string; worktree: string; reason: "dirty" | "ignored" }> = [];
515	    for (const [unitId, entry] of Object.entries(this.state.units)) {
516	      if (unitIds && !unitIds.includes(unitId)) continue;
517	      if (!fs.existsSync(entry.worktree)) continue;
518	      const status = gitResult(entry.worktree, ["status", "--porcelain", "--ignored"]);
519	      if (!status.ok) out.push({ unitId, worktree: entry.worktree, reason: "dirty" });
520	      else if (status.stdout.trim()) {
521	        const tracked = gitResult(entry.worktree, ["status", "--porcelain"]);
522	        out.push({ unitId, worktree: entry.worktree, reason: tracked.stdout.trim() ? "dirty" : "ignored" });
523	      }
524	    }
525	    return out;
526	  }
527	
528	  /** A missing worktree is recoverable only when its retained branch is already merged. */
529	  canRecoverMissingWorktree(unitId: string): boolean {
530	    const entry = this.state.units[unitId];
531	    return Boolean(
532	      entry && entry.integratedCommit === undefined && !fs.existsSync(entry.worktree) && this.mergedUnitCommit(entry),
533	    );
534	  }
535	
536	  /** Integrity check at runner start: an unmerged missing worktree fails closed instead of rerunning blind. */
537	  missingWorktrees(): Array<{ unitId: string; worktree: string }> {
538	    return Object.entries(this.state.units)
539	      .filter(([, entry]) =>
540	        entry.integratedCommit === undefined && !fs.existsSync(entry.worktree) && !this.mergedUnitCommit(entry))
541	      .map(([unitId, entry]) => ({ unitId, worktree: entry.worktree }));
542	  }
543	
544	  /** Drop clean remaining unit worktrees; branches, dirty files and the integration worktree stay. */
545	  disposeAllUnits(): void {
546	    for (const entry of Object.values(this.state.units)) this.removeWorktree(entry.worktree, true);
547	  }
548	
549	  unitState(unitId: string): OperationGitUnit | undefined {
550	    return this.state.units[unitId];
551	  }
552	
553	  /** Fixed author, no signing and no hooks (pre or post): integration must not depend on the operator's Git config. */
554	  private mechanicalGitConfig(): string[] {
555	    const base = ["-c", "user.name=Nexus", "-c", "user.email=nexus@localhost", "-c", "commit.gpgsign=false"];
556	    try {
557	      fs.mkdirSync(this.hooksDir, { recursive: true });
558	      return [...base, "-c", `core.hooksPath=${this.hooksDir}`];
559	    } catch {
560	      // Without a usable hooks directory, `--no-verify` still skips pre-commit/commit-msg; post-* hooks may run.
561	      return base;
562	    }
563	  }
564	
565	  private abortStaleMerge(): void {
566	    try {
567	      const gitDirPath = git(this.plan.integrationWorktree, ["rev-parse", "--git-dir"]);
568	      const gitDir = path.isAbsolute(gitDirPath) ? gitDirPath : path.resolve(this.plan.integrationWorktree, gitDirPath);
569	      if (fs.existsSync(path.join(gitDir, "MERGE_HEAD"))) {
570	        gitResult(this.plan.integrationWorktree, ["merge", "--abort"]);
571	      }
572	    } catch {
573	      // No readable git dir: the merge command below reports the real problem.
574	    }
575	  }
576	
577	  /** Remove what a verifier may have written on top of the merge; the merge commit itself is untouched. */
578	  private cleanIntegrationWorktree(): void {
579	    gitResult(this.plan.integrationWorktree, ["reset", "--hard", "HEAD"]);
580	    gitResult(this.plan.integrationWorktree, ["clean", "-fd"]);
581	  }
582	
583	  private integrationIntegrity(commit: string, expectedTip: string): { ok: boolean; reason?: string } {
584	    const branch = gitResult(this.plan.integrationWorktree, ["rev-parse", "--abbrev-ref", "HEAD"]);
585	    if (!branch.ok || branch.stdout.trim() !== this.plan.integrationBranch) {
586	      return { ok: false, reason: "integration verification moved the worktree off the integration branch" };
587	    }
588	    const head = gitResult(this.plan.integrationWorktree, ["rev-parse", "HEAD"]);
589	    if (!head.ok || head.stdout.trim() !== expectedTip) {
590	      return { ok: false, reason: "integration verification changed the integration tip; it was rewritten or rewound" };
591	    }
592	    if (!gitResult(this.plan.integrationWorktree, ["merge-base", "--is-ancestor", commit, "HEAD"]).ok) {
593	      return { ok: false, reason: "integration branch no longer contains the unit commit; it was rewritten or rewound" };
594	    }
595	    return { ok: true };
596	  }
597	
598	  private restoreIntegration(commit: string): string | undefined {
599	    const restored = gitResult(this.plan.integrationWorktree, [
600	      "checkout", "--force", "-B", this.plan.integrationBranch, commit,
601	    ]);
602	    if (!restored.ok) return `could not restore the integration branch: ${restored.stderr.trim() || "git checkout failed"}`;
603	    const cleaned = gitResult(this.plan.integrationWorktree, ["clean", "-fd"]);
604	    if (!cleaned.ok) return `could not clean the restored integration worktree: ${cleaned.stderr.trim() || "git clean failed"}`;
605	    return undefined;
606	  }
607	
608	  private mergedUnitCommit(entry: OperationGitUnit): string | undefined {
609	    const resolved = gitResult(this.plan.repoRoot, ["rev-parse", "--verify", `refs/heads/${entry.branch}^{commit}`]);
610	    const commit = resolved.stdout.trim();
611	    if (!resolved.ok || !commit || commit === entry.baseCommit) return undefined;
612	    return gitResult(this.plan.integrationWorktree, ["merge-base", "--is-ancestor", commit, "HEAD"]).ok
613	      ? commit
614	      : undefined;
615	  }
616	
617	  private removeWorktree(worktree: string, preserveIfNotClean = false): void {
618	    if (!fs.existsSync(worktree)) return;
619	    if (preserveIfNotClean) {
620	      const status = gitResult(worktree, ["status", "--porcelain", "--ignored"]);
621	      if (!status.ok || status.stdout.trim()) return;
622	    }
623	    gitResult(this.plan.repoRoot, ["worktree", "remove", "--force", worktree]);
624	  }
625	
626	  /** Re-run the unit's verifier on the merged tree. The unit's own evidence already proved it executed tests. */
627	  private verifyMerged(command: string): { ok: boolean; reason?: string } {
628	    const deadlineMs = (this.options.verifyTimeoutSecs ?? verifierTimeoutSecs()) * 1000;
629	    const ran = runVerifierShell(command, this.plan.integrationWorktree, deadlineMs);
630	    if (ran.success) return { ok: true };
631	    const tail = ran.output.trim().split("\n").slice(-6).join("\n");
632	    if (ran.exitCode === 126 || ran.exitCode === 127) {
633	      return {
634	        ok: false,
635	        reason: `integration verification could not run on the merged tree (exit ${ran.exitCode}): ${command}\n${environmentHint()}` + (tail ? `\n${tail}` : ""),
636	      };
637	    }
638	    return {
639	      ok: false,
640	      reason:
641	        `integration verification failed on the merged tree: ${command}${ran.timedOut ? " (timed out)" : ""}` +
642	        (tail ? `\n${tail}` : ""),
643	    };
644	  }
645	}
